package com.stillthinkingofaname.welcome;

import java.util.*;
import org.bukkit.*;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

public final class StarterKitService {
 public final JavaPlugin p; final Set<UUID> claimed=new HashSet<>(); final Map<UUID,Long> first=new HashMap<>(); final Map<UUID,Integer> warnings=new HashMap<>(); static final long THREE_DAYS_MILLIS=3L*24*60*60*1000;
 public StarterKitService(JavaPlugin p){this.p=p;load();}
 private void load(){for(String s:p.getConfig().getStringList("claimed-starter-kit-players"))try{claimed.add(UUID.fromString(s));}catch(IllegalArgumentException ignored){} ConfigurationSection f=p.getConfig().getConfigurationSection("first-join-times");if(f!=null)for(String s:f.getKeys(false))try{first.put(UUID.fromString(s),f.getLong(s));}catch(IllegalArgumentException ignored){} ConfigurationSection w=p.getConfig().getConfigurationSection("warning-shown-count");if(w!=null)for(String s:w.getKeys(false))try{warnings.put(UUID.fromString(s),w.getInt(s));}catch(IllegalArgumentException ignored){}}
 void save(String k,Map<?,?> m){for(var e:m.entrySet())p.getConfig().set(k+"."+e.getKey(),e.getValue());p.saveConfig();} void saveClaimed(){p.getConfig().set("claimed-starter-kit-players",new ArrayList<>(claimed.stream().map(UUID::toString).toList()));p.saveConfig();}
 public void join(Player q){UUID id=q.getUniqueId();if(!first.containsKey(id)){first.put(id,System.currentTimeMillis());save("first-join-times",first);}if(!claimed.contains(id)){Long t=first.get(id);if(t!=null){boolean expired=System.currentTimeMillis()-t>THREE_DAYS_MILLIS,armor=high(q);if(expired||armor){int n=warnings.getOrDefault(id,0);if(n<2){q.sendMessage(ChatColor.RED+(expired?"Starter kit sudah hangus! Batas waktu klaim (3 hari) telah berakhir.":"Starter kit sudah hangus! Kamu sudah memiliki armor tier tinggi."));warnings.put(id,n+1);save("warning-shown-count",warnings);}}else q.sendMessage(ChatColor.GREEN+"Klaim starter kit: "+ChatColor.WHITE+"/starterkit");}}}
 boolean high(Player q){int n=0;for(ItemStack i:q.getInventory().getArmorContents())if(i!=null&&high(i.getType())&&++n>=4)return true;for(ItemStack i:q.getInventory().getContents())if(i!=null&&high(i.getType())&&++n>=4)return true;return false;} boolean high(Material m){return switch(m){case DIAMOND_HELMET,DIAMOND_CHESTPLATE,DIAMOND_LEGGINGS,DIAMOND_BOOTS,NETHERITE_HELMET,NETHERITE_CHESTPLATE,NETHERITE_LEGGINGS,NETHERITE_BOOTS->true;default->false;};}
 boolean claim(Player q){UUID id=q.getUniqueId();if(claimed.contains(id)){q.sendMessage(ChatColor.RED+"Kamu sudah mengklaim starter kit!");return true;}Long t=first.get(id);if(t==null){q.sendMessage(ChatColor.RED+"Data bergabung tidak ditemukan. Hubungi admin.");return true;}if(System.currentTimeMillis()-t>THREE_DAYS_MILLIS||high(q)){q.sendMessage(ChatColor.RED+"Starter kit sudah hangus! "+(high(q)?"Kamu sudah memiliki armor tier tinggi.":"Waktu klaim (3 hari) telah berakhir."));claimed.add(id);saveClaimed();return true;}give(q);claimed.add(id);saveClaimed();q.sendMessage(ChatColor.GREEN+"✔ Starter kit berhasil diklaim!");return true;}
 void give(Player q){List<?> xs=p.getConfig().getList("starter-kit.inventory-items");if(xs!=null)for(Object x:xs){ItemStack i=item(x);if(i!=null)q.getInventory().addItem(i).values().forEach(d->q.getWorld().dropItemNaturally(q.getLocation(),d));}ConfigurationSection a=p.getConfig().getConfigurationSection("starter-kit.armor");if(a!=null){if(a.contains("helmet"))q.getInventory().setHelmet(item(a.get("helmet")));if(a.contains("chestplate"))q.getInventory().setChestplate(item(a.get("chestplate")));if(a.contains("leggings"))q.getInventory().setLeggings(item(a.get("leggings")));if(a.contains("boots"))q.getInventory().setBoots(item(a.get("boots")));}if(p.getConfig().get("starter-kit.offhand")!=null)q.getInventory().setItemInOffHand(item(p.getConfig().get("starter-kit.offhand")));q.updateInventory();}
 ItemStack item(Object x){try{if(x instanceof Map m){if(m.containsKey("==")||m.containsKey("id"))return ItemStack.deserialize(m);if(m.containsKey("material"))return new ItemStack(Material.valueOf((String)m.get("material")),((Number)m.getOrDefault("amount",1)).intValue());}if(x instanceof ConfigurationSection s)return ItemStack.deserialize(s.getValues(true));}catch(Exception e){p.getLogger().warning("Failed to deserialize item: "+e.getMessage());}return null;}
}
